const bgMusic=document.createElement('audio');bgMusic.src='/media/warm-floop-background.mp3';bgMusic.loop=true;bgMusic.preload='metadata';bgMusic.volume=.18;document.body.append(bgMusic);const musicButton=el('button','♫','music-toggle');musicButton.type='button';musicButton.setAttribute('aria-label','Play background music');musicButton.title='Play background music';musicButton.setAttribute('aria-pressed','false');musicButton.hidden=true;let musicWanted=true,musicStarted=false,musicBusy=false;function filmPlaying(){return [...document.querySelectorAll('#featured video,#film-content video')].some(v=>!v.paused&&!v.ended&&!v.muted)}function musicState(){const playing=!bgMusic.paused;musicButton.textContent=playing?'♫':'♪';musicButton.setAttribute('aria-pressed',String(playing));musicButton.setAttribute('aria-label',playing?'Mute background music':'Play background music');musicButton.title=playing?'Mute background music':'Play background music'}async function playMusic(){if(!musicWanted||document.hidden||filmPlaying()||dialog.open||musicBusy)return;musicBusy=true;try{await bgMusic.play();musicStarted=true}catch{musicButton.title='Click to play music';musicButton.setAttribute('aria-label','Click to play background music')}finally{musicBusy=false;musicState()}}function syncMusic(){if(document.hidden||dialog.open||filmPlaying()||!musicWanted)bgMusic.pause();else if(musicStarted)playMusic();musicState()}musicButton.addEventListener('click',()=>{if(!bgMusic.paused){musicWanted=false;bgMusic.pause()}else{musicWanted=true;playMusic()}musicState()});function beginMusic(e){if(e.target.closest('#film-content,#gallery,#featured'))return;if(!musicStarted&&musicWanted)playMusic()}document.addEventListener('pointerdown',beginMusic);document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&!musicStarted&&musicWanted&&!e.target.closest('button,video'))playMusic()});document.addEventListener('visibilitychange',syncMusic);for(const event of ['play','pause','ended','volumechange'])document.addEventListener(event,e=>{if(e.target.matches?.('#featured video,#film-content video'))syncMusic()},true);new MutationObserver(syncMusic).observe(dialog,{attributes:true,attributeFilter:['open']});bgMusic.addEventListener('play',musicState);bgMusic.addEventListener('pause',musicState);bgMusic.addEventListener('error',()=>{musicButton.textContent='!';musicButton.title='Music could not load. Click to retry.';musicButton.setAttribute('aria-label','Retry background music');musicStarted=false});
